import type { GatewaySetup } from '../../api/GatewayKeys';

function envLines(setup: GatewaySetup): string {
  return [
    '# Generated by AI Runtime Governance. Contains a gateway access key; do not commit.',
    `ARG_GATEWAY_BASE_URL=${setup.baseUrl}`,
    `ARG_GATEWAY_KEY=${setup.token}`,
    `ARG_MODEL=${setup.models[0] ?? 'model-id'}`,
    `OPENAI_BASE_URL=${setup.baseUrl}`,
    `OPENAI_API_KEY=${setup.token}`,
    'ARG_TRACE_EXPORT=gateway',
  ].join('\n');
}

function hereString(json: string): string {
  return `@'\n${json.trim()}\n'@`;
}

export function buildPowerShellScript(setup: GatewaySetup): string {
  return `# AI Runtime Governance setup. Run in the project you want to trace.
# The provider secrets stay on the governance server; this file only carries an access key.
$ErrorActionPreference = 'Stop'

$incoming = ${hereString(setup.openCodeConfig)} | ConvertFrom-Json
$target = Join-Path (Get-Location) 'opencode.jsonc'
$config = if (Test-Path -LiteralPath $target) { Get-Content -LiteralPath $target -Raw | ConvertFrom-Json } else { [pscustomobject]@{} }
if ($config.PSObject.Properties.Name -contains 'provider' -and $null -ne $config.provider) {
    $config.provider | Add-Member -NotePropertyName governance -NotePropertyValue $incoming.provider.governance -Force
} else {
    $config | Add-Member -NotePropertyName provider -NotePropertyValue ([pscustomobject]@{ governance = $incoming.provider.governance }) -Force
}
$config | Add-Member -NotePropertyName model -NotePropertyValue $incoming.model -Force
$config | Add-Member -NotePropertyName '$schema' -NotePropertyValue 'https://opencode.ai/config.json' -Force
$utf8 = New-Object System.Text.UTF8Encoding($false)
[IO.File]::WriteAllText($target, ($config | ConvertTo-Json -Depth 20), $utf8)

if ($env:APPDATA) {
    $vsPath = Join-Path $env:APPDATA 'Code\\User\\ChatLanguageModels.json'
    New-Item -ItemType Directory -Path (Split-Path -Parent $vsPath) -Force | Out-Null
    $entry = ${hereString(setup.vsCodeConfig)} | ConvertFrom-Json
    $existing = if (Test-Path -LiteralPath $vsPath) { @(Get-Content -LiteralPath $vsPath -Raw | ConvertFrom-Json) } else { @() }
    $merged = @($existing | Where-Object { $_.name -ne 'AI Runtime Governance' }) + @($entry)
    [IO.File]::WriteAllText($vsPath, (ConvertTo-Json -InputObject @($merged) -Depth 20), $utf8)
}

$envDir = Join-Path $HOME '.arg'
New-Item -ItemType Directory -Path $envDir -Force | Out-Null
$envText = ${hereString(envLines(setup))}
[IO.File]::WriteAllText((Join-Path $envDir 'tracing.env'), $envText, $utf8)

Write-Host 'AI Runtime Governance setup applied.'
Write-Host 'Restart OpenCode and select provider "AI Runtime Governance".'
`;
}

export function buildBashScript(setup: GatewaySetup): string {
  return `#!/usr/bin/env bash
# AI Runtime Governance setup. Run in the project you want to trace.
# The provider secrets stay on the governance server; this file only carries an access key.
set -euo pipefail

mkdir -p ~/.config/opencode
cat > ~/.config/opencode/opencode.json <<'JSON'
${setup.openCodeConfig.trim()}
JSON

if [ "$(uname)" = "Darwin" ]; then
  VS_DIR="$HOME/Library/Application Support/Code/User"
else
  VS_DIR="$HOME/.config/Code/User"
fi
mkdir -p "$VS_DIR"
cat > "$VS_DIR/ChatLanguageModels.json" <<'JSON'
${setup.vsCodeConfig.trim()}
JSON

mkdir -p ~/.arg
cat > ~/.arg/tracing.env <<'ENV'
${envLines(setup)}
ENV

echo 'AI Runtime Governance setup applied.'
echo 'Restart OpenCode and select provider "AI Runtime Governance".'
`;
}
